"use client";

import Image from "next/image";
import Link from "next/link";
import { useEffect, useState, useMemo, useCallback } from "react";
import {
  ArrowLeft,
  ExternalLink,
  Copy,
  CheckCircle2,
  Globe,
  TrendingUp,
  TrendingDown,
  DollarSign,
  Users,
  Calendar,
  Activity,
  BarChart3,
  Plus,
  Minus,
  RefreshCw,
  Clock,
  ArrowUpRight,
  ArrowDownRight,
} from "lucide-react";
import { motion } from "framer-motion";
import { usePrivy, useWallets } from "@privy-io/react-auth";
import { Button } from "@/components/ui/button";
import { formatWalletAddress } from "@/lib/wallet-privy";
import { toast } from "sonner";
import { ethers } from "ethers";
import { SwapInterface } from "@/components/SwapInterface";
import TradingChart from "@/components/TradingChart";

// Extended CL Pool ABI
const CL_POOL_ABI = [
  "function liquidity() view returns (uint256)",
  "function token0() view returns (address)",
  "function token1() view returns (address)",
  "function fee() view returns (uint24)",
  "function slot0() view returns (uint160 sqrtPriceX96, int24 tick, uint16 observationIndex, uint16 observationCardinality, uint16 observationCardinalityNext, uint8 feeProtocol, bool unlocked)",
];

// ERC-20 ABI
const ERC20_ABI = [
  "function symbol() view returns (string)",
  "function name() view returns (string)",
  "function decimals() view returns (uint8)",
  "function totalSupply() view returns (uint256)",
  "function balanceOf(address) view returns (uint256)",
];

// Pool Factory ABI to get pool creation info
const POOL_FACTORY_ABI = [
  "event PoolCreated(address indexed token0, address indexed token1, uint24 indexed fee, int24 tickSpacing, address pool)",
];

interface PoolData {
  liquidity: string | null;
  token0: string | null;
  token1: string | null;
  token0Symbol: string | null;
  token1Symbol: string | null;
  token0Name: string | null;
  token1Name: string | null;
  token0Decimals: number | null;
  token1Decimals: number | null;
  token0Reserve: string | null;
  token1Reserve: string | null;
  fee: string | null;
  price: string | null;
  priceChange24h: string | null;
  volume24h: string | null;
  tvl: string | null;
  lpCount: number | null;
  createdAt: number | null;
  creator: string | null;
}

interface PresaleData {
  _id: string;
  appName: string;
  appLogo?: string | null;
  tickerName: string;
  description?: string;
  erc20Symbol?: string;
  erc20Name?: string;
  appXHandle?: string;
  isXConnected?: boolean;
  appLink?: string;
  creator?: string;
  totalRaised?: string;
  contributorCount?: number;
  contractStartTime?: number;
  endTime?: number;
  crowdfundAddress?: string;
  poolLauncherToken?: string | null;
  tokenToPair?: string | null;
  projectToken?: string | null;
}

interface Transaction {
  hash: string;
  type: "swap" | "add" | "remove";
  timestamp: number;
  amount0: string;
  amount1: string;
  from: string;
  to: string;
}

interface ChartData {
  time: string;
  value: number;
}

type TimeRange = "1h" | "24h" | "7d" | "30d" | "all";

type Props = { poolAddress: string };

export default function PoolDetailsClient({ poolAddress }: Props) {
  const [poolData, setPoolData] = useState<PoolData | null>(null);
  const [presaleData, setPresaleData] = useState<PresaleData | null>(null);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [chartData, setChartData] = useState<ChartData[]>([]);
  const [timeRange, setTimeRange] = useState<TimeRange>("24h");
  const [isLoading, setIsLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copiedAddress, setCopiedAddress] = useState<string | null>(null);

  const { authenticated } = usePrivy();
  const { wallets } = useWallets();
  const walletAddress = wallets[0]?.address || null;

  // RPC endpoints with fallbacks
  const rpcUrls = [
    "https://base.llamarpc.com",
    "https://base-mainnet.g.alchemy.com/v2/demo",
    "https://mainnet.base.org",
    "https://1rpc.io/base",
  ];

  // Get provider with fallback
  const getProvider = useCallback(async (): Promise<ethers.JsonRpcProvider> => {
    let lastError: Error | null = null;
    for (const url of rpcUrls) {
      try {
        const provider = new ethers.JsonRpcProvider(url);
        await provider.getBlockNumber();
        return provider;
      } catch (err) {
        lastError = err as Error;
        continue;
      }
    }
    throw lastError || new Error("All RPC endpoints failed");
  }, []);

  // Helper function to fetch pool stats for a specific address
  const fetchPoolStatsForAddress = useCallback(async (address: string, provider: ethers.JsonRpcProvider) => {
    try {
      const poolContract = new ethers.Contract(address, CL_POOL_ABI, provider);

      // Fetch basic pool data with better error handling
      let liquidity, token0, token1, slot0, fee;
      
      try {
        [liquidity, token0, token1, slot0, fee] = await Promise.all([
          poolContract.liquidity().catch((e: any) => {
            console.warn("Failed to fetch liquidity:", e.message);
            return null;
          }),
          poolContract.token0().catch((e: any) => {
            console.warn("Failed to fetch token0:", e.message);
            return null;
          }),
          poolContract.token1().catch((e: any) => {
            console.warn("Failed to fetch token1:", e.message);
            return null;
          }),
          poolContract.slot0().catch((e: any) => {
            console.warn("Failed to fetch slot0:", e.message);
            return null;
          }),
          poolContract.fee().catch((e: any) => {
            console.warn("Failed to fetch fee:", e.message);
            return null;
          }),
        ]);
      } catch (error: any) {
        console.error("Error calling pool contract:", error);
        // Try with minimal ABI (just token0 and token1)
        const minimalABI = [
          "function token0() view returns (address)",
          "function token1() view returns (address)",
        ];
        const minimalContract = new ethers.Contract(address, minimalABI, provider);
        [token0, token1] = await Promise.all([
          minimalContract.token0().catch(() => null),
          minimalContract.token1().catch(() => null),
        ]);
        liquidity = null;
        slot0 = null;
        fee = null;
      }

      console.log("📊 Fetched pool data:", { token0, token1, liquidity: liquidity !== null, fee: fee !== null });
      
      if (!token0 || !token1) {
        console.error("❌ Missing token0 or token1:", { token0, token1 });
        throw new Error("Pool contract does not have token0 or token1. This might not be a valid CL pool.");
      }

      // Fetch token info
      const token0Contract = new ethers.Contract(token0, ERC20_ABI, provider);
      const token1Contract = new ethers.Contract(token1, ERC20_ABI, provider);

      const [token0Symbol, token0Name, token0Decimals, token1Symbol, token1Name, token1Decimals] = await Promise.all([
        token0Contract.symbol().catch(() => null),
        token0Contract.name().catch(() => null),
        token0Contract.decimals().catch(() => null),
        token1Contract.symbol().catch(() => null),
        token1Contract.name().catch(() => null),
        token1Contract.decimals().catch(() => null),
      ]);

      // Calculate reserves (simplified - would need actual pool balance calls)
      const token0Reserve = await token0Contract.balanceOf(address).catch(() => null);
      const token1Reserve = await token1Contract.balanceOf(address).catch(() => null);

      // Format liquidity
      let formattedLiquidity: string | null = null;
      let tvl: string | null = null;
      if (liquidity) {
        const liquidityBigInt = BigInt(liquidity.toString());
        const liquidityUSDC = Number(liquidityBigInt) / 1e6;
        formattedLiquidity = `$${liquidityUSDC.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
        tvl = formattedLiquidity;
      }

      // Calculate price (simplified - would need proper sqrtPriceX96 calculation)
      let price: string | null = null;
      if (slot0 && token0Decimals && token1Decimals) {
        const sqrtPriceX96 = slot0[0];
        // Simplified price calculation
        const priceNum = Number(sqrtPriceX96) ** 2 / (2 ** 192);
        price = `$${priceNum.toFixed(6)}`;
      }

      // Format reserves
      const formatReserve = (reserve: bigint | null, decimals: number | null): string | null => {
        if (!reserve || !decimals) return null;
        const amount = Number(reserve) / 10 ** decimals;
        return amount.toLocaleString(undefined, { maximumFractionDigits: 6 });
      };

      return {
        liquidity: formattedLiquidity,
        token0,
        token1,
        token0Symbol,
        token1Symbol,
        token0Name,
        token1Name,
        token0Decimals,
        token1Decimals,
        token0Reserve: formatReserve(token0Reserve, token0Decimals),
        token1Reserve: formatReserve(token1Reserve, token1Decimals),
        fee: fee ? `${Number(fee) / 10000}%` : null,
        price,
        priceChange24h: "+2.5%", // Placeholder - would need historical data
        volume24h: "$12,345", // Placeholder - would need transaction history
        tvl,
        lpCount: null, // Would need to query LP token holders
        createdAt: null, // Would need to query pool creation event
        creator: null, // Would need to query pool creation event
      };
    } catch (err: any) {
      console.error("Error fetching pool stats for address:", address, err);
      throw err;
    }
  }, []);

  // Fetch pool statistics
  const fetchPoolStats = useCallback(async () => {
    try {
      const provider = await getProvider();
      
      // First, validate address format
      if (!ethers.isAddress(poolAddress)) {
        throw new Error(`Invalid address format: ${poolAddress}`);
      }

      // First, verify the address is a contract
      console.log("🔍 Checking if address is a contract:", poolAddress);
      let code;
      try {
        code = await provider.getCode(poolAddress);
        console.log("📦 Contract code length:", code?.length || 0);
        if (!code || code === "0x" || code.length < 10) {
          // Address has no code - might be EOA or not deployed yet
          console.warn("⚠️ Address has no code, will try to find pool from presale contract in main fetch");
          throw new Error(`Address ${poolAddress} is not a contract or has no code`);
        }
      } catch (err: any) {
        console.error("❌ Contract verification failed:", err);
        throw err;
      }

      // If we get here, the address has code, so fetch pool stats
      return await fetchPoolStatsForAddress(poolAddress, provider);
    } catch (err: any) {
      console.error("Error in fetchPoolStats:", err);
      throw err;
    }
  }, [poolAddress, getProvider, fetchPoolStatsForAddress]);

  // Fetch transaction history from BaseScan
  const fetchTransactions = useCallback(async () => {
    try {
      // BaseScan API endpoint
      const apiKey = process.env.NEXT_PUBLIC_BASESCAN_API_KEY || "";
      const url = `https://api.basescan.org/api?module=account&action=txlist&address=${poolAddress}&startblock=0&endblock=99999999&page=1&offset=5&sort=desc&apikey=${apiKey}`;

      const response = await fetch(url);
      if (!response.ok) throw new Error("Failed to fetch transactions");

      const data = await response.json();
      if (data.status !== "1" || !data.result) return [];

      // Parse transactions (simplified - would need to parse actual swap/add/remove events)
      const txs: Transaction[] = data.result.slice(0, 5).map((tx: any) => ({
        hash: tx.hash,
        type: "swap" as const, // Simplified - would need to parse events
        timestamp: parseInt(tx.timeStamp),
        amount0: "0",
        amount1: "0",
        from: tx.from,
        to: tx.to,
      }));

      return txs;
    } catch (err) {
      console.error("Error fetching transactions:", err);
      return [];
    }
  }, [poolAddress]);

  // Fetch chart data
  const fetchChartData = useCallback(async (range: TimeRange) => {
    try {
      // Generate mock data based on time range
      // In production, this would fetch from DEX aggregator or on-chain data
      const now = Date.now();
      let startTime: number;
      let points: number;

      switch (range) {
        case "1h":
          startTime = now - 3600000;
          points = 60;
          break;
        case "24h":
          startTime = now - 86400000;
          points = 24;
          break;
        case "7d":
          startTime = now - 7 * 86400000;
          points = 7;
          break;
        case "30d":
          startTime = now - 30 * 86400000;
          points = 30;
          break;
        default:
          startTime = now - 90 * 86400000;
          points = 90;
      }

      const data: ChartData[] = [];
      const interval = (now - startTime) / points;
      let basePrice = 0.05;

      for (let i = 0; i < points; i++) {
        const time = new Date(startTime + i * interval).toISOString();
        basePrice += (Math.random() - 0.5) * 0.01;
        data.push({
          time,
          value: Math.max(0.01, basePrice),
        });
      }

      return data;
    } catch (err) {
      console.error("Error fetching chart data:", err);
      return [];
    }
  }, []);

  // Main data fetch
  const fetchAllData = useCallback(async (isRefresh = false) => {
    if (isRefresh) {
      setIsRefreshing(true);
    } else {
      setIsLoading(true);
    }
    setError(null);

    try {
      // Fetch pool stats first - if this fails, we should show an error
      console.log("🚀 Starting to fetch pool data for:", poolAddress);
      let stats;
      try {
        stats = await fetchPoolStats();
        console.log("✅ Pool stats fetched:", stats ? "Success" : "Null");
        if (!stats) {
          throw new Error("Pool contract returned no data. This might not be a valid CL pool.");
        }
        setPoolData(stats);
        console.log("✅ Pool data set successfully");
      } catch (err: any) {
        console.error("❌ Failed to fetch pool stats:", err);
        console.error("Error details:", {
          message: err.message,
          stack: err.stack,
          poolAddress,
        });
        throw err; // Re-throw to be caught by outer catch
      }

      // Fetch other data in parallel (these can fail without breaking the page)
      const [txs, chart] = await Promise.all([
        fetchTransactions().catch((err) => {
          console.warn("Failed to fetch transactions:", err);
          return [];
        }),
        fetchChartData(timeRange).catch((err) => {
          console.warn("Failed to fetch chart data:", err);
          return [];
        }),
      ]);

      setTransactions(txs);
      setChartData(chart);

      // Fetch presale data to potentially get the correct pool address
      const backendUrl = process.env.NEXT_PUBLIC_BACKEND_URL || "http://localhost:3001";
      const response = await fetch(`${backendUrl}/api/presales`, {
        headers: { Accept: "application/json" },
        cache: "no-store",
      });

        let actualPoolAddress = poolAddress; // Default to the provided address

      if (response.ok) {
        const payload = await response.json();
        const presale = (payload.data || []).find(
          (p: any) => p.pool === poolAddress || p.liquidityPool === poolAddress || p.crowdfundAddress
        );

        if (presale) {
          let logoUrl: string | null = null;
          if (presale.appLogo) {
            if (typeof presale.appLogo === "string") {
              if (presale.appLogo.startsWith("http")) {
                logoUrl = presale.appLogo;
              } else {
                const logoPath = presale.appLogo.startsWith("/") ? presale.appLogo : `/${presale.appLogo}`;
                logoUrl = `${backendUrl}${logoPath}`;
              }
            }
          }

          setPresaleData({
            _id: presale._id,
            appName: presale.appName || "Unknown",
            appLogo: logoUrl,
            tickerName: presale.tickerName || "TOKEN",
            description: presale.description || "",
            erc20Symbol: presale.erc20Symbol,
            erc20Name: presale.erc20Name,
            appXHandle: presale.appXHandle,
            isXConnected: presale.isXConnected || false,
            appLink: presale.appLink,
            creator: presale.creator,
            totalRaised: presale.totalRaised,
            contributorCount: presale.contributorCount || 0,
            contractStartTime: presale.contractStartTime,
            endTime: presale.endTime,
            crowdfundAddress: presale.crowdfundAddress,
            poolLauncherToken: presale.poolLauncherToken,
            tokenToPair: presale.tokenToPair,
            projectToken: presale.projectToken,
          });
        }
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load pool data");
      console.error("Error fetching pool data:", err);
    } finally {
      setIsLoading(false);
      setIsRefreshing(false);
    }
  }, [poolAddress, fetchPoolStats, fetchTransactions, fetchChartData, timeRange]);

  // Initial load
  useEffect(() => {
    fetchAllData();
  }, [fetchAllData]);

  // Auto-refresh every 1 minute
  useEffect(() => {
    const interval = setInterval(() => {
      fetchAllData(true);
    }, 60000); // 1 minute

    return () => clearInterval(interval);
  }, [fetchAllData]);

  // Update chart when time range changes
  useEffect(() => {
    fetchChartData(timeRange).then(setChartData);
  }, [timeRange, fetchChartData]);

  const copyToClipboard = (text: string, label: string) => {
    navigator.clipboard.writeText(text);
    setCopiedAddress(label);
    toast.success("Address copied to clipboard");
    setTimeout(() => setCopiedAddress(null), 2000);
  };

  const formatUSDC = (value: string | undefined): string => {
    if (!value) return "$0.00";
    try {
      const num = BigInt(value);
      const usdc = Number(num) / 1e6;
      return `$${usdc.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    } catch {
      return "$0.00";
    }
  };

  const formatTime = (timestamp: number): string => {
    return new Date(timestamp * 1000).toLocaleString();
  };

  const getTransactionTypeLabel = (type: string): string => {
    switch (type) {
      case "swap":
        return "Swap";
      case "add":
        return "Add Liquidity";
      case "remove":
        return "Remove Liquidity";
      default:
        return "Transaction";
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#EC4E02] mx-auto mb-4"></div>
          <p className="text-white/60">Loading pool data...</p>
        </div>
      </div>
    );
  }

  if (error || (!poolData && !isLoading)) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center px-4">
        <div className="text-center max-w-md">
          <div className="mb-6">
            <div className="h-16 w-16 rounded-full bg-red-500/20 flex items-center justify-center mx-auto mb-4">
              <Activity className="h-8 w-8 text-red-500" />
            </div>
            <p className="text-red-500 text-xl font-bold mb-2">Failed to load pool data</p>
            <p className="text-white/60 text-sm mb-2">{error || "Pool not found"}</p>
            <p className="text-white/40 text-xs mb-4">
              Pool Address: <span className="font-mono">{formatWalletAddress(poolAddress)}</span>
            </p>
            <div className="text-left bg-white/5 rounded-lg p-4 text-xs text-white/60 space-y-2">
              <p className="font-semibold text-white/80 mb-2">Possible reasons:</p>
              <ul className="list-disc list-inside space-y-1">
                <li>The address might not be a valid CL pool contract</li>
                <li>The pool contract might not exist on Base network</li>
                <li>RPC endpoints might be temporarily unavailable</li>
                <li>The contract ABI might not match the pool implementation</li>
              </ul>
            </div>
          </div>
          <div className="flex gap-3 justify-center">
            <Link href="/">
              <Button variant="outline">Go Back</Button>
            </Link>
            <Button
              onClick={() => {
                setError(null);
                fetchAllData();
              }}
              className="bg-[#EC4E02] hover:bg-[#EC4E02]/80"
            >
              <RefreshCw className="h-4 w-4 mr-2" />
              Retry
            </Button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-black text-white">
      {/* Header */}
      <div className="border-b border-white/10 bg-[#0F0F10]">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
          <div className="flex items-center justify-between">
            <Link href="/" className="inline-flex items-center gap-2 text-white/60 hover:text-white transition-colors">
              <ArrowLeft className="h-4 w-4" />
              <span>Back to Dashboard</span>
            </Link>
            <button
              onClick={() => fetchAllData(true)}
              disabled={isRefreshing}
              className="inline-flex items-center gap-2 text-white/60 hover:text-white transition-colors disabled:opacity-50"
            >
              <RefreshCw className={`h-4 w-4 ${isRefreshing ? "animate-spin" : ""}`} />
              <span className="hidden sm:inline">Refresh</span>
            </button>
          </div>
        </div>
      </div>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 lg:gap-8">
          {/* Main Content */}
          <div className="lg:col-span-2 space-y-6">
            {/* Pool Header */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              className="bg-[#0F0F10] border border-white/10 rounded-2xl p-6"
            >
              <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4">
                {presaleData?.appLogo && (
                  <div className="relative h-16 w-16 rounded-xl overflow-hidden border border-white/10 shrink-0">
                    <Image
                      src={presaleData.appLogo}
                      alt={presaleData.appName}
                      fill
                      className="object-cover"
                      unoptimized
                    />
                  </div>
                )}
                <div className="flex-1 min-w-0">
                  <h1 className="text-2xl font-bold text-white mb-2 truncate">
                    {presaleData?.appName || "Pool"} ({presaleData?.tickerName || "TOKEN"})
                  </h1>
                  {presaleData?.description && (
                    <p className="text-white/60 text-sm mb-4 line-clamp-2">{presaleData.description}</p>
                  )}
                  <div className="flex flex-wrap items-center gap-4 text-sm">
                    {presaleData?.appLink && (
                      <a
                        href={presaleData.appLink}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center gap-1 text-[#EC4E02] hover:text-[#EC4E02]/80 transition-colors"
                      >
                        <Globe className="h-4 w-4" />
                        <span>Website</span>
                        <ExternalLink className="h-3 w-3" />
                      </a>
                    )}
                    {presaleData?.appXHandle && (
                      <a
                        href={`https://x.com/${presaleData.appXHandle}`}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center gap-1 text-[#EC4E02] hover:text-[#EC4E02]/80 transition-colors"
                      >
                        <span>@{presaleData.appXHandle}</span>
                        <ExternalLink className="h-3 w-3" />
                      </a>
                    )}
                  </div>
                </div>
              </div>
            </motion.div>

            {/* Pool Statistics */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.1 }}
              className="bg-[#0F0F10] border border-white/10 rounded-2xl p-6"
            >
              <h2 className="text-xl font-bold text-white mb-4">Pool Statistics</h2>
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                <div className="space-y-1">
                  <p className="text-white/60 text-xs">TVL</p>
                  <p className="text-white font-bold text-lg">{poolData.tvl || "--"}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-white/60 text-xs">24h Volume</p>
                  <p className="text-white font-bold text-lg">{poolData.volume24h || "--"}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-white/60 text-xs">Price</p>
                  <div className="flex items-center gap-2">
                    <p className="text-white font-bold text-lg">{poolData.price || "--"}</p>
                    {poolData.priceChange24h && (
                      <span
                        className={`text-xs font-semibold ${
                          poolData.priceChange24h.startsWith("+") ? "text-green-500" : "text-red-500"
                        }`}
                      >
                        {poolData.priceChange24h}
                      </span>
                    )}
                  </div>
                </div>
                <div className="space-y-1">
                  <p className="text-white/60 text-xs">Fee</p>
                  <p className="text-white font-bold text-lg">{poolData.fee || "--"}</p>
                </div>
              </div>
            </motion.div>

            {/* Trading Chart */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.2 }}
              className="bg-[#0F0F10] border border-white/10 rounded-2xl p-6"
            >
              <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between mb-4 gap-4">
                <h2 className="text-xl font-bold text-white">Price Chart</h2>
                <div className="flex gap-2">
                  {(["1h", "24h", "7d", "30d", "all"] as TimeRange[]).map((range) => (
                    <button
                      key={range}
                      onClick={() => setTimeRange(range)}
                      className={`px-3 py-1 rounded-lg text-sm font-semibold transition-colors ${
                        timeRange === range
                          ? "bg-[#EC4E02] text-white"
                          : "bg-white/5 text-white/60 hover:bg-white/10"
                      }`}
                    >
                      {range.toUpperCase()}
                    </button>
                  ))}
                </div>
              </div>
              <div className="h-64 w-full">
                <TradingChart data={chartData} />
              </div>
            </motion.div>

            {/* Transaction History */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.3 }}
              className="bg-[#0F0F10] border border-white/10 rounded-2xl p-6"
            >
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-xl font-bold text-white">Recent Transactions</h2>
                <a
                  href={`https://basescan.org/address/${poolAddress}#tokentxns`}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="text-sm text-[#EC4E02] hover:text-[#EC4E02]/80 transition-colors flex items-center gap-1"
                >
                  View All
                  <ExternalLink className="h-3 w-3" />
                </a>
              </div>
              <div className="space-y-3">
                {transactions.length > 0 ? (
                  transactions.map((tx) => (
                    <div
                      key={tx.hash}
                      className="flex items-center justify-between p-3 bg-white/5 rounded-lg border border-white/5"
                    >
                      <div className="flex items-center gap-3 flex-1 min-w-0">
                        <div
                          className={`p-2 rounded-lg ${
                            tx.type === "swap"
                              ? "bg-blue-500/20 text-blue-500"
                              : tx.type === "add"
                                ? "bg-green-500/20 text-green-500"
                                : "bg-red-500/20 text-red-500"
                          }`}
                        >
                          {tx.type === "swap" ? (
                            <ArrowUpRight className="h-4 w-4" />
                          ) : tx.type === "add" ? (
                            <Plus className="h-4 w-4" />
                          ) : (
                            <Minus className="h-4 w-4" />
                          )}
                        </div>
                        <div className="flex-1 min-w-0">
                          <p className="text-white font-semibold text-sm">{getTransactionTypeLabel(tx.type)}</p>
                          <p className="text-white/60 text-xs truncate">{formatTime(tx.timestamp)}</p>
                        </div>
                      </div>
                      <a
                        href={`https://basescan.org/tx/${tx.hash}`}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="text-[#EC4E02] hover:text-[#EC4E02]/80 transition-colors ml-2"
                      >
                        <ExternalLink className="h-4 w-4" />
                      </a>
                    </div>
                  ))
                ) : (
                  <p className="text-white/60 text-center py-8">No transactions found</p>
                )}
              </div>
            </motion.div>

            {/* Pool Information */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.4 }}
              className="bg-[#0F0F10] border border-white/10 rounded-2xl p-6"
            >
              <h2 className="text-xl font-bold text-white mb-4">Pool Information</h2>
              <div className="space-y-4">
                <div className="flex items-center justify-between py-3 border-b border-white/5">
                  <span className="text-white/60">Liquidity</span>
                  <span className="text-white font-bold">{poolData.liquidity || "--"}</span>
                </div>
                <div className="flex items-center justify-between py-3 border-b border-white/5">
                  <span className="text-white/60">Token 0</span>
                  <div className="flex items-center gap-2">
                    {poolData.token0Symbol && (
                      <span className="text-white/80 text-sm font-semibold">{poolData.token0Symbol}</span>
                    )}
                    <span className="text-white font-mono text-sm">
                      {poolData.token0 ? formatWalletAddress(poolData.token0) : "--"}
                    </span>
                    {poolData.token0 && (
                      <>
                        <button
                          onClick={() => copyToClipboard(poolData.token0!, "token0")}
                          className="text-white/40 hover:text-white transition-colors"
                        >
                          {copiedAddress === "token0" ? (
                            <CheckCircle2 className="h-4 w-4" />
                          ) : (
                            <Copy className="h-4 w-4" />
                          )}
                        </button>
                        <a
                          href={`https://basescan.org/address/${poolData.token0}`}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-[#EC4E02] hover:text-[#EC4E02]/80 transition-colors"
                        >
                          <ExternalLink className="h-4 w-4" />
                        </a>
                      </>
                    )}
                  </div>
                </div>
                <div className="flex items-center justify-between py-3 border-b border-white/5">
                  <span className="text-white/60">Token 1</span>
                  <div className="flex items-center gap-2">
                    {poolData.token1Symbol && (
                      <span className="text-white/80 text-sm font-semibold">{poolData.token1Symbol}</span>
                    )}
                    <span className="text-white font-mono text-sm">
                      {poolData.token1 ? formatWalletAddress(poolData.token1) : "--"}
                    </span>
                    {poolData.token1 && (
                      <>
                        <button
                          onClick={() => copyToClipboard(poolData.token1!, "token1")}
                          className="text-white/40 hover:text-white transition-colors"
                        >
                          {copiedAddress === "token1" ? (
                            <CheckCircle2 className="h-4 w-4" />
                          ) : (
                            <Copy className="h-4 w-4" />
                          )}
                        </button>
                        <a
                          href={`https://basescan.org/address/${poolData.token1}`}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-[#EC4E02] hover:text-[#EC4E02]/80 transition-colors"
                        >
                          <ExternalLink className="h-4 w-4" />
                        </a>
                      </>
                    )}
                  </div>
                </div>
                {poolData.token0Reserve && poolData.token1Reserve && (
                  <>
                    <div className="flex items-center justify-between py-3 border-b border-white/5">
                      <span className="text-white/60">Token 0 Reserve</span>
                      <span className="text-white font-bold">{poolData.token0Reserve}</span>
                    </div>
                    <div className="flex items-center justify-between py-3 border-b border-white/5">
                      <span className="text-white/60">Token 1 Reserve</span>
                      <span className="text-white font-bold">{poolData.token1Reserve}</span>
                    </div>
                  </>
                )}
                {poolData.lpCount !== null && (
                  <div className="flex items-center justify-between py-3 border-b border-white/5">
                    <span className="text-white/60">Liquidity Providers</span>
                    <span className="text-white font-bold">{poolData.lpCount}</span>
                  </div>
                )}
                {poolData.createdAt && (
                  <div className="flex items-center justify-between py-3 border-b border-white/5">
                    <span className="text-white/60 flex items-center gap-2">
                      <Calendar className="h-4 w-4" />
                      Created
                    </span>
                    <span className="text-white font-bold">{formatTime(poolData.createdAt)}</span>
                  </div>
                )}
                {poolData.creator && (
                  <div className="flex items-center justify-between py-3 border-b border-white/5">
                    <span className="text-white/60">Creator</span>
                    <div className="flex items-center gap-2">
                      <span className="text-white font-mono text-sm">{formatWalletAddress(poolData.creator)}</span>
                      <a
                        href={`https://basescan.org/address/${poolData.creator}`}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="text-[#EC4E02] hover:text-[#EC4E02]/80 transition-colors"
                      >
                        <ExternalLink className="h-4 w-4" />
                      </a>
                    </div>
                  </div>
                )}
                <div className="flex items-center justify-between py-3">
                  <span className="text-white/60">Pool Address</span>
                  <div className="flex items-center gap-2">
                    <span className="text-white font-mono text-sm">{formatWalletAddress(poolAddress)}</span>
                    <button
                      onClick={() => copyToClipboard(poolAddress, "pool")}
                      className="text-white/40 hover:text-white transition-colors"
                    >
                      {copiedAddress === "pool" ? (
                        <CheckCircle2 className="h-4 w-4" />
                      ) : (
                        <Copy className="h-4 w-4" />
                      )}
                    </button>
                    <a
                      href={`https://basescan.org/address/${poolAddress}`}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="text-[#EC4E02] hover:text-[#EC4E02]/80 transition-colors"
                    >
                      <ExternalLink className="h-4 w-4" />
                    </a>
                  </div>
                </div>
              </div>
            </motion.div>

            {/* Presale Info (if available) */}
            {presaleData && (
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.5 }}
                className="bg-[#0F0F10] border border-white/10 rounded-2xl p-6"
              >
                <h2 className="text-xl font-bold text-white mb-4">Presale Information</h2>
                <div className="space-y-4">
                  {presaleData.totalRaised && (
                    <div className="flex items-center justify-between py-3 border-b border-white/5">
                      <span className="text-white/60 flex items-center gap-2">
                        <DollarSign className="h-4 w-4" />
                        Total Raised
                      </span>
                      <span className="text-white font-bold">{formatUSDC(presaleData.totalRaised)}</span>
                    </div>
                  )}
                  {presaleData.contributorCount !== undefined && (
                    <div className="flex items-center justify-between py-3 border-b border-white/5">
                      <span className="text-white/60 flex items-center gap-2">
                        <Users className="h-4 w-4" />
                        Contributors
                      </span>
                      <span className="text-white font-bold">{presaleData.contributorCount}</span>
                    </div>
                  )}
                  {presaleData.creator && (
                    <div className="flex items-center justify-between py-3">
                      <span className="text-white/60">Creator</span>
                      <div className="flex items-center gap-2">
                        <span className="text-white font-mono text-sm">{formatWalletAddress(presaleData.creator)}</span>
                        <a
                          href={`https://basescan.org/address/${presaleData.creator}`}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-[#EC4E02] hover:text-[#EC4E02]/80 transition-colors"
                        >
                          <ExternalLink className="h-4 w-4" />
                        </a>
                      </div>
                    </div>
                  )}
                </div>
              </motion.div>
            )}
          </div>

          {/* Sidebar */}
          <div className="space-y-6">
            {/* Swap Interface */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.3 }}
              className="bg-[#0F0F10] border border-white/10 rounded-2xl p-6"
            >
              <h2 className="text-xl font-bold text-white mb-4">Swap</h2>
              {presaleData?.projectToken ? (
                <SwapInterface
                  tokenAddress={presaleData.projectToken}
                  tokenSymbol={presaleData.tickerName || presaleData.erc20Symbol || "TOKEN"}
                  poolCreated={true}
                  poolAddress={poolAddress}
                  crowdfundAddress={presaleData.crowdfundAddress || null}
                />
              ) : (
                <div className="text-center py-8 text-white/60">
                  <p>Loading token information...</p>
                </div>
              )}
            </motion.div>

            {/* Liquidity Management */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.4 }}
              className="bg-[#0F0F10] border border-white/10 rounded-2xl p-6"
            >
              <h2 className="text-xl font-bold text-white mb-4">Liquidity</h2>
              <div className="space-y-3">
                <Button
                  className="w-full bg-[#EC4E02] hover:bg-[#EC4E02]/80 text-white"
                  onClick={() => {
                    window.open(`https://aerodrome.finance/pools/${poolAddress}`, "_blank");
                  }}
                >
                  <Plus className="h-4 w-4 mr-2" />
                  Add Liquidity
                </Button>
                <Button
                  variant="outline"
                  className="w-full border-white/20 hover:bg-white/10"
                  onClick={() => {
                    window.open(`https://aerodrome.finance/pools/${poolAddress}`, "_blank");
                  }}
                >
                  <Minus className="h-4 w-4 mr-2" />
                  Remove Liquidity
                </Button>
                <a
                  href={`https://aerodrome.finance/pools/${poolAddress}`}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="block w-full"
                >
                  <Button variant="outline" className="w-full border-white/20 hover:bg-white/10">
                    <ExternalLink className="h-4 w-4 mr-2" />
                    View on Aerodrome
                  </Button>
                </a>
              </div>
            </motion.div>

            {/* Quick Stats */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.5 }}
              className="bg-[#0F0F10] border border-white/10 rounded-2xl p-6"
            >
              <h2 className="text-xl font-bold text-white mb-4">Quick Stats</h2>
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <span className="text-white/60 text-sm">Status</span>
                  <span className="px-2 py-1 rounded bg-green-500/20 text-green-500 text-xs font-bold">Active</span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-white/60 text-sm">Network</span>
                  <span className="text-white text-sm font-bold">Base</span>
                </div>
                {poolData.fee && (
                  <div className="flex items-center justify-between">
                    <span className="text-white/60 text-sm">Fee</span>
                    <span className="text-white text-sm font-bold">{poolData.fee}</span>
                  </div>
                )}
              </div>
            </motion.div>
          </div>
        </div>
      </main>
    </div>
  );
}
